class Bankkonto:
    def __init__(self, inhaber):
        self.inhaber = inhaber
        self.kontostand = 0

    def einzahlen(self, betrag):
        self.kontostand += betrag

    def abheben(self, betrag):
        if betrag > self.kontostand:
            print("Nicht genug Geld!")
        else:
            self.kontostand -= betrag

konto = Bankkonto("Lena")
konto.einzahlen(100)
konto.abheben(30)
konto.abheben(500)        # Nicht genug Geld!
print(konto.kontostand)   # 70

class Rechteck:
    def __init__(self, breite, hoehe):
        self.breite = breite
        self.hoehe = hoehe

    def flaeche(self):
        return self.breite * self.hoehe

    def ist_groesser_als(self, anderes):
        return self.flaeche() > anderes.flaeche()

a = Rechteck(3, 4)
b = Rechteck(2, 5)
print(a.flaeche())           # 12
print(a.ist_groesser_als(b)) # True

class Rucksack:
    inhalt = []                 # falsch: eine Liste für ALLE

    def einpacken(self, ding):
        self.inhalt.append(ding)

a = Rucksack()
b = Rucksack()
a.einpacken("Jause")
print(b.inhalt)   # ['Jause'] – ups!

class Rucksack2:
    def __init__(self):
        self.inhalt = []        # richtig: jeder Rucksack hat seine eigene Liste

